import QuartzCore

let A = CommandLine.arguments
let pkg = URL(fileURLWithPath: A[1])
let KEYS = (ProcessInfo.processInfo.environment["KEYS"] ?? "8192,16384,32768,49152,65536,81920,98304").split(separator: ",").map { Int($0)! }
let REPS = Int(ProcessInfo.processInfo.environment["REPS"] ?? "10")!
let SEG = [8192, 8192, 16384, 32768, 32768]
let NCH = 16
setvbuf(stdout, nil, _IOLBF, 0)
guard dec_init(A[2]) > 0 else { print("dec_init failed"); exit(1) }

typealias Spec = (type: NDArray.ScalarType, shape: [Int], strides: [Int], nbytes: Int)
func specOf(_ d: InferenceValue.Descriptor?) -> Spec {
    guard let d, case .ndArray(let a) = d else { fatalError("not an ndarray") }
    return (a.scalarType, a.shape, a.preferredStrides, a.minimumByteCount)
}
final class Ten {
    let buf: MTLBuffer, type: NDArray.ScalarType, shape: [Int], strides: [Int], idx: Int32
    init(_ s: Spec) {
        let page = Int(getpagesize()), n = (max(s.nbytes, 16) + page - 1) / page * page
        buf = dev.makeBuffer(length: n, options: .storageModeShared)!
        memset(buf.contents(), 0, n)
        type = s.type; shape = s.shape; strides = s.strides
        wrapped.append(buf); idx = Int32(wrapped.count - 1)
    }
    var av: InferenceFunction.AsyncValue { InferenceFunction.AsyncValue(unsafeBuffer: buf, scalarType: type, shape: shape, strides: strides) }
    func mut() -> InferenceFunction.AsyncMutableValue { InferenceFunction.AsyncMutableValue(unsafeBuffer: buf, scalarType: type, shape: shape, strides: strides) }
    func zero() { memset(buf.contents(), 0, buf.length) }
}

