let t0 = CACurrentMediaTime()
let model = try await AIModel(contentsOf: pkg, options: SpecializationOptions(preferredComputeUnitKind: .neuralEngine))
func fn(_ n: String) -> InferenceFunction { guard let f = try! model.loadFunction(named: n) else { fatalError("no \(n)") }; return f }
let fA = fn("dva0"), fBA = fn("dvba"), fB1 = fn("dvb1")
print(String(format: "loaded in %.1f s", CACurrentMediaTime() - t0))
func ins(_ f: InferenceFunction) -> [String: Ten] { Dictionary(uniqueKeysWithValues: f.descriptor.inputNames.map { ($0, Ten(specOf(f.descriptor.inputDescriptor(of: $0)))) }) }
func outs(_ f: InferenceFunction) -> [String: Ten] { Dictionary(uniqueKeysWithValues: f.descriptor.outputNames.map { ($0, Ten(specOf(f.descriptor.outputDescriptor(of: $0)))) }) }
func avs(_ d: [String: Ten], except: Set<String> = []) -> [String: InferenceFunction.AsyncValue] {
    var r: [String: InferenceFunction.AsyncValue] = [:]; for (k, v) in d where !except.contains(k) { r[k] = v.av }; return r
}
func fill16(_ t: Ten, _ v: Float) { let p = t.buf.contents().bindMemory(to: Float16.self, capacity: t.buf.length / 2); for i in 0..<(t.buf.length / 2) { p[i] = Float16(v) } }

let inA = ins(fA), inBA = ins(fBA), inB1 = ins(fB1)
let setX = outs(fA), setA = outs(fBA), setB = outs(fBA), outB1 = outs(fB1)
let O = inBA["o"]!
var rng = SystemRandomNumberGenerator()
for t in [inA["x"]!] { let p = t.buf.contents().bindMemory(to: Float16.self, capacity: t.buf.length / 2); for i in 0..<(t.buf.length / 2) { p[i] = Float16(Float.random(in: -0.05...0.05, using: &rng)) } }
fill16(inA["cos"]!, 1); fill16(inBA["cos"]!, 1)
for n in ["q", "g", "kt", "vt"] { precondition(setX[n]!.strides == setA[n]!.strides, "strides of \(n)") }
let st: [UInt32] = [setX["q"]!.strides[0], setX["q"]!.strides[1], setX["kt"]!.strides[0], setX["kt"]!.strides[1],
                    setX["vt"]!.strides[0], setX["vt"]!.strides[1], setX["g"]!.strides[0], setX["g"]!.strides[1], O.strides[1]].map { UInt32($0) }
print("q \(setX["q"]!.shape) \(setX["q"]!.strides); o \(O.shape) \(O.strides)")
// synthetic KV cache (GPU layer 99)
var start = 0
for L in SEG {
    let k = dev.makeBuffer(length: 4 * 256 * L, options: .storageModeShared)!, v = dev.makeBuffer(length: 4 * 256 * L, options: .storageModeShared)!
    let ks = dev.makeBuffer(length: 4 * L * 2, options: .storageModeShared)!, vs = dev.makeBuffer(length: 4 * L * 2, options: .storageModeShared)!
    for b in [k, v] { let p = b.contents().bindMemory(to: Int8.self, capacity: b.length); for i in 0..<b.length { p[i] = Int8.random(in: -127...127, using: &rng) } }
    for (b, x) in [(ks, Float16(0.02)), (vs, Float16(0.01))] { let p = b.contents().bindMemory(to: Float16.self, capacity: b.length / 2); for i in 0..<(b.length / 2) { p[i] = x } }
    var hi: [Int32] = []
    for b in [k, ks, v, vs] { wrapped.append(b); hi.append(Int32(wrapped.count - 1)) }
    precondition(dec_seg(99, Int32(start), Int32(L), hi[0], hi[1], hi[2], hi[3]) > 0)
    start += L
}
let stream = ComputeStream(commandQueue: queue)

func gpu(_ set: [String: Ten], _ p0: Int, wait: Bool) {
    let cb = queue.makeCommandBuffer()!
    let h: [Int32] = [set["q"]!.idx, set["g"]!.idx, set["kt"]!.idx, set["vt"]!.idx, O.idx]
    h.withUnsafeBufferPointer { hp in st.withUnsafeBufferPointer { sp in precondition(encode(cb, 99, hp.baseAddress!, sp.baseAddress!, p0)) } }
    cb.commit()
    if wait { cb.waitUntilCompleted() }
}
let aStatic = avs(inA), baStatic = avs(inBA, except: ["o", "xr_prev"])
func fused(_ p0: Int, sync: Bool, gpuOn: Bool = true, aneOn: Bool = true) async throws {
    if aneOn { _ = try enc_dva0(fA, aStatic, setX, stream); if sync { await stream.currentWorkCompleted() } }
    if gpuOn { gpu(setX, p0, wait: sync) }
    var prev = setX, useA = true
    for _ in 0..<(NCH - 1) {
        let cur = useA ? setA : setB
        if aneOn {
            var i = baStatic; i["o"] = O.av; i["xr_prev"] = prev["xr"]!.av
            _ = try enc_dvba(fBA, i, cur, stream); if sync { await stream.currentWorkCompleted() }
        }
        if gpuOn { gpu(cur, p0, wait: sync) }
        prev = cur; useA.toggle()
    }
    if aneOn { _ = try enc_dvb1(fB1, ["o": O.av, "x": prev["xr"]!.av], outB1, stream) }
    await stream.currentWorkCompleted()
    if gpuOn && !aneOn { let cb = queue.makeCommandBuffer()!; cb.commit(); cb.waitUntilCompleted() }
}
func zeroChain() { for d in [setX, setA, setB, outB1] { for (_, t) in d { t.zero() } }; O.zero() }
func median(_ a: [Double]) -> Double { a.sorted()[a.count / 2] }
func tm(_ reps: Int = REPS, _ body: () async throws -> Void) async rethrows -> Double {
    var ts: [Double] = []
    for _ in 0..<reps { let t = CACurrentMediaTime(); try await body(); ts.append((CACurrentMediaTime() - t) * 1e3) }
    return median(ts)
}
// references: 16 x the chunk's verify entry, encoded on the stream
var refs: [Int: () async throws -> Void] = [:]
for c in [16384, 32768, 65536, 98304] {
    let f = fn("v8_\(c / 1024)k"), i = ins(f), o = outs(f), iv = avs(i)
    let e: (InferenceFunction, [String: InferenceFunction.AsyncValue], [String: Ten], ComputeStream) throws -> [String: InferenceFunction.AsyncValue] =
        c == 16384 ? enc_v8_16k : c == 32768 ? enc_v8_32k : c == 65536 ? enc_v8_64k : enc_v8_96k
    refs[c] = { for _ in 0..<NCH { _ = try e(f, iv, o, stream) }; await stream.currentWorkCompleted() }
}
// ---- sync bridges (v8/build_sync_bridge.py, specialized for the GPU, on the same stream): ANE outputs -> cpq -> the
// buffers the GPU attention reads (Metal orders our command buffer after cpq's write); our o -> cpo -> part B's input
let modelG = try await AIModel(contentsOf: URL(fileURLWithPath: A[3]), options: SpecializationOptions(preferredComputeUnitKind: .gpu))
let fCQ = try modelG.loadFunction(named: "cpq")!, fCO = try modelG.loadFunction(named: "cpo")!
let Z = ins(fCQ)["z"]!, QG = outs(fCQ), OG = ins(fCO)["o"]!, O2 = outs(fCO)
print("bridges: q2 \(QG["q2"]!.strides), og \(OG.strides), o2 \(O2["o2"]!.strides)")
let stG: [UInt32] = [QG["q2"]!.strides[0], QG["q2"]!.strides[1], QG["kt2"]!.strides[0], QG["kt2"]!.strides[1],
                     QG["vt2"]!.strides[0], QG["vt2"]!.strides[1], QG["g2"]!.strides[0], QG["g2"]!.strides[1], OG.strides[1]].map { UInt32($0) }
func gpuG(_ p0: Int) {
    let cb = queue.makeCommandBuffer()!
    let h: [Int32] = [QG["q2"]!.idx, QG["g2"]!.idx, QG["kt2"]!.idx, QG["vt2"]!.idx, OG.idx]
    h.withUnsafeBufferPointer { hp in stG.withUnsafeBufferPointer { sp in precondition(encode(cb, 99, hp.baseAddress!, sp.baseAddress!, p0)) } }
    cb.commit()
}
var shownKeys = false
// the cross-device values unbound: dva0 / dvba return xr, q, g, kt, vt and cpo returns o2 as AsyncValues, passed on as
// inputs (Core AI's dependency tracking); cpq writes into QG (bound), which the GPU attention reads
func bridged(_ p0: Int) async throws {
    var r = try enc_dva0_u(fA, aStatic, setX, stream)
    if !shownKeys { print("encode (unbound cross-device outputs) returned keys: \(r.keys.sorted())"); shownKeys = true }
    for k in 0..<NCH {
        _ = try enc_cpq(fCQ, ["q": r["q"]!, "g": r["g"]!, "kt": r["kt"]!, "vt": r["vt"]!, "z": Z.av], QG, stream)
        gpuG(p0)
        let ro = try enc_cpo_u(fCO, ["o": OG.av, "z": Z.av], O2, stream)
        if k < NCH - 1 {
            var i = baStatic; i["o"] = ro["o2"]!; i["xr_prev"] = r["xr"]!
            r = try enc_dvba_u(fBA, i, k % 2 == 0 ? setA : setB, stream)
        } else {
            _ = try enc_dvb1(fB1, ["o": ro["o2"]!, "x": r["xr"]!], outB1, stream)
        }
    }
    await stream.currentWorkCompleted()
}
func zeroAll() { zeroChain(); for (_, t) in QG { t.zero() }; for (_, t) in O2 { t.zero() }; OG.zero() }
func maxdiff(_ a: Data, _ b: Data) -> Float {
    a.withUnsafeBytes { pa in b.withUnsafeBytes { pb in
        zip(pa.bindMemory(to: Float16.self), pb.bindMemory(to: Float16.self)).map { abs(Float($0) - Float($1)) }.max() ?? 0 } }
}
// correctness: stream vs sync, bit for bit (and vs a second stream run)
let P0 = 8184
zeroChain(); try await fused(P0, sync: true)
let ySync = Data(bytes: outB1["y"]!.buf.contents(), count: outB1["y"]!.buf.length)
zeroChain(); try await fused(P0, sync: false)
let yStr = Data(bytes: outB1["y"]!.buf.contents(), count: outB1["y"]!.buf.length)
let nz = ySync.withUnsafeBytes { $0.bindMemory(to: UInt16.self).filter { $0 != 0 }.count }
print("y stream == y sync: \(ySync == yStr) (nonzero halves \(nz) of \(ySync.count / 2))")
var bridgedOK = true
for rep in 0..<3 {
    zeroAll(); try await bridged(P0)
    let yBr = Data(bytes: outB1["y"]!.buf.contents(), count: outB1["y"]!.buf.length)
    let d = maxdiff(yBr, ySync)
    print("bridged stream run \(rep): max |y - y sync| = \(d)")
    bridgedOK = bridgedOK && d == 0
}
// ---- all Core AI: the attention stand-in "att" (a GPU Core AI function, trivial compute) between the ANE parts,
// chained only through Core AI futures: Core AI's own ANE <-> GPU handoff, stream (one wait) vs sync (wait per call)
let fAT = try modelG.loadFunction(named: "att")!
func allcai(sync: Bool) async throws {
    var r = try enc_dva0_u(fA, aStatic, setX, stream); if sync { await stream.currentWorkCompleted() }
    for k in 0..<NCH {
        let ra = try fAT.encode(inputs: ["q": r["q"]!, "g": r["g"]!, "kt": r["kt"]!, "vt": r["vt"]!, "z": Z.av], to: stream)
        if sync { await stream.currentWorkCompleted() }
        if k < NCH - 1 {
            var i = baStatic; i["o"] = ra["o"]!; i["xr_prev"] = r["xr"]!
            r = try enc_dvba_u(fBA, i, k % 2 == 0 ? setA : setB, stream); if sync { await stream.currentWorkCompleted() }
        } else {
            _ = try enc_dvb1(fB1, ["o": ra["o"]!, "x": r["xr"]!], outB1, stream)
        }
    }
    await stream.currentWorkCompleted()
}
zeroAll(); try await allcai(sync: true)
let yAS = Data(bytes: outB1["y"]!.buf.contents(), count: outB1["y"]!.buf.length)
var allOK = true
for rep in 0..<3 {
    zeroAll(); try await allcai(sync: false)
    let d = maxdiff(Data(bytes: outB1["y"]!.buf.contents(), count: outB1["y"]!.buf.length), yAS)
    print("all-Core-AI stream run \(rep): max |y - y sync| = \(d)"); allOK = allOK && d == 0
}
func yNow() -> Data { Data(bytes: outB1["y"]!.buf.contents(), count: outB1["y"]!.buf.length) }
var ys: [Data] = [], yt: [Data] = []
for _ in 0..<3 { zeroAll(); try await allcai(sync: true); ys.append(yNow()) }
for _ in 0..<3 { zeroAll(); try await allcai(sync: false); yt.append(yNow()) }
print("determinism: sync vs sync \(maxdiff(ys[0], ys[1])), \(maxdiff(ys[0], ys[2])); stream vs stream \(maxdiff(yt[0], yt[1])), \(maxdiff(yt[0], yt[2]))")
var yf: [Data] = []
for _ in 0..<3 { zeroAll(); try await fused(P0, sync: true); yf.append(yNow()) }
print("raw-GPU fused sync vs itself: \(maxdiff(yf[0], yf[1])), \(maxdiff(yf[0], yf[2])); NaN in y sync: \(ys[0].withUnsafeBytes { $0.bindMemory(to: Float16.self).contains { $0.isNaN } })")
// ANE-only chains: (F) futures dva0_u -> dvba_u (xr_prev = the future, o = O constant) x15 -> dvb1; (B) bound buffers
func aneF(sync: Bool) async throws {
    var r = try enc_dva0_u(fA, aStatic, setX, stream); if sync { await stream.currentWorkCompleted() }
    for k in 0..<(NCH - 1) {
        var i = baStatic; i["o"] = O.av; i["xr_prev"] = r["xr"]!
        r = try enc_dvba_u(fBA, i, k % 2 == 0 ? setA : setB, stream); if sync { await stream.currentWorkCompleted() }
    }
    _ = try enc_dvb1(fB1, ["o": O.av, "x": r["xr"]!], outB1, stream)
    await stream.currentWorkCompleted()
}
func fillO() { let p = O.buf.contents().bindMemory(to: Float16.self, capacity: O.buf.length / 2); for i in 0..<(O.buf.length / 2) { p[i] = Float16(Float(i % 7) * 0.01) } }
for (name, f) in [("futures", { (s: Bool) async throws in try await aneF(sync: s) }), ("bound", { (s: Bool) async throws in try await fused(P0, sync: s, gpuOn: false) })] {
    var a: [Data] = [], b: [Data] = []
    for _ in 0..<2 { zeroAll(); fillO(); try await f(true); a.append(yNow()) }
    for _ in 0..<3 { zeroAll(); fillO(); try await f(false); b.append(yNow()) }
    print("ANE-only \(name): sync vs sync \(maxdiff(a[0], a[1])); stream vs sync \(maxdiff(b[0], a[0])), \(maxdiff(b[1], a[0])), \(maxdiff(b[2], a[0]))")
}
